<script setup lang="ts">
/**
 * Importing Speaking parts from a file ("mockmee/speaking-parts"): each part with its questions, the
 * examiner's audio and sample answers, so neither is generated by AI each time. The file is checked
 * first (what would be made or updated, and anything wrong); nothing is saved until it is clean.
 */
const open = defineModel<boolean>('open', { default: false })
const props = defineProps<{ exam: 'IELTS' | 'MULTILEVEL' }>()
const emit = defineEmits<{ imported: [] }>()
const toast = useToast()

interface Check { parts: number, created: number, updated: number, questions: number, audio: number, samples: number, errors: { index: number, message: string }[], saved: boolean }
const text = ref('')
const fileName = ref<string | null>(null)
const check = ref<Check | null>(null)
const busy = ref(false)
const parsed = computed(() => {
  if (!text.value.trim()) return null
  try {
    return JSON.parse(text.value)
  } catch {
    return undefined
  }
})
watch(open, (v) => {
  if (!v) return
  text.value = ''
  fileName.value = null
  check.value = null
})
watch(text, () => (check.value = null))

async function pick(e: Event) {
  const input = e.target as HTMLInputElement
  const file = input.files?.[0]
  if (!file) return
  fileName.value = file.name
  text.value = await file.text()
  input.value = ''
  await run(true)
}
async function run(dryRun: boolean) {
  if (!parsed.value) return
  busy.value = true
  try {
    const body = Array.isArray(parsed.value) ? { exam: props.exam, parts: parsed.value } : { exam: props.exam, ...parsed.value }
    check.value = await $fetch<Check>('/api/admin/speaking-parts/import', { method: 'POST', body, query: dryRun ? { dryRun: 1 } : {} })
    if (check.value.saved) {
      toast.add({ title: 'Speaking imported', description: `${check.value.created} new, ${check.value.updated} updated.`, color: 'success' })
      open.value = false
      emit('imported')
    }
  } catch (e) {
    toast.add({ title: 'Not imported', description: errorMessage(e), color: 'error' })
  } finally {
    busy.value = false
  }
}

const EXAMPLE = {
  format: 'mockmee/speaking-parts',
  version: 1,
  parts: [
    {
      exam: 'IELTS', partNumber: 1, title: 'Hometown',
      questions: [
        { text: 'Where is your hometown?', audioUrl: 'https://cdn.example.com/speaking/hometown-1.mp3', sampleAnswer: 'I come from Samarkand, an ancient city in the centre of Uzbekistan...' },
        { text: 'What do you like most about it?', audioUrl: null, sampleAnswer: 'What I like most is...' }
      ]
    },
    {
      exam: 'IELTS', partNumber: 2, title: 'A memorable trip',
      cueCard: '<p>Describe a memorable trip you took.</p><ul><li>where you went</li><li>who you went with</li><li>what you did</li></ul><p>and explain why it was memorable.</p>',
      audioUrl: 'https://cdn.example.com/speaking/trip-card.mp3',
      sampleAnswer: 'I would like to talk about a trip I took to Khiva two years ago...'
    }
  ]
}
function downloadExample() {
  const url = URL.createObjectURL(new Blob([JSON.stringify(EXAMPLE, null, 2)], { type: 'application/json' }))
  const a = Object.assign(document.createElement('a'), { href: url, download: 'speaking-parts-example.json' })
  a.click()
  URL.revokeObjectURL(url)
}
</script>

<template>
  <UModal
    v-model:open="open"
    title="Import Speaking parts"
    description="Questions with the examiner's audio and sample answers: imported audio is played as it is, and sample answers are shown in feedback instead of being written by AI each time."
    :ui="{ content: 'sm:max-w-2xl' }"
  >
    <template #body>
      <div class="grid gap-4">
        <div class="flex flex-wrap items-center gap-2">
          <label>
            <input
              type="file"
              accept="application/json,.json"
              class="hidden"
              data-testid="speaking-import-file"
              @change="pick"
            >
            <UButton
              as="span"
              :label="fileName ?? 'Choose a .json file'"
              icon="i-lucide-file-json"
              color="neutral"
              variant="outline"
              class="cursor-pointer"
            />
          </label>
          <span class="text-sm text-muted">or paste it below</span>
          <UButton
            label="Example file"
            icon="i-lucide-download"
            color="neutral"
            variant="link"
            size="sm"
            class="ms-auto"
            @click="downloadExample"
          />
        </div>
        <UTextarea
          v-model="text"
          :rows="8"
          placeholder="{ &quot;format&quot;: &quot;mockmee/speaking-parts&quot;, &quot;parts&quot;: [ … ] }"
          class="w-full font-mono text-xs"
          data-testid="speaking-import-text"
        />
        <p
          v-if="parsed === undefined"
          class="text-sm text-error"
        >
          This is not valid JSON.
        </p>
        <details class="text-sm text-muted">
          <summary class="cursor-pointer">
            What a file holds
          </summary>
          <ul class="list-disc ps-5 mt-2 grid gap-1">
            <li><code>parts</code>: each with <code>exam</code> (IELTS or MULTILEVEL, else the exam picked in the builder), <code>partNumber</code>, <code>title</code>, <code>cueCard</code> (HTML), <code>imageUrl</code>, <code>prepSeconds</code>, <code>speakSeconds</code>.</li>
            <li><code>questions</code>: plain strings, or <code>{ text, audioUrl, sampleAnswer }</code>.</li>
            <li>A long turn (IELTS Part 2, Multilevel Parts 2 and 3) has its own <code>audioUrl</code> and <code>sampleAnswer</code>.</li>
            <li>Audio is an <code>https://</code> address or an embedded <code>data:audio/…;base64,</code> file (stored on import).</li>
            <li>A part with the <code>id</code> from an Export is updated instead of added: export, fill in the audio and samples, import back.</li>
          </ul>
        </details>

        <div
          v-if="check"
          class="rounded-lg ring ring-default p-3 grid gap-2"
          data-testid="speaking-import-check"
        >
          <p class="text-sm">
            <span class="font-semibold text-highlighted">{{ check.parts }} parts</span>:
            {{ check.created }} new, {{ check.updated }} updated · {{ check.questions }} questions · {{ check.audio }} audio · {{ check.samples }} sample answers
          </p>
          <UAlert
            v-if="check.errors.length"
            color="error"
            variant="subtle"
            icon="i-lucide-circle-alert"
            :title="`${check.errors.length} to fix before importing`"
          >
            <template #description>
              <ul class="list-disc ps-4 grid gap-0.5">
                <li
                  v-for="err in check.errors.slice(0, 20)"
                  :key="err.index"
                >
                  {{ err.message }}
                </li>
              </ul>
            </template>
          </UAlert>
        </div>
      </div>
    </template>
    <template #footer>
      <div class="flex justify-end gap-2 w-full">
        <UButton
          label="Cancel"
          color="neutral"
          variant="ghost"
          @click="open = false"
        />
        <UButton
          v-if="!check"
          label="Check"
          icon="i-lucide-list-checks"
          :loading="busy"
          :disabled="!parsed"
          @click="run(true)"
        />
        <UButton
          v-else
          :label="`Import ${check.parts} parts`"
          icon="i-lucide-file-down"
          :loading="busy"
          :disabled="!!check.errors.length"
          data-testid="speaking-import-go"
          @click="run(false)"
        />
      </div>
    </template>
  </UModal>
</template>
